head.script:
scwin.onpageload = function() {
    //탭버튼 라인의 우측 버튼의 경우, As-Is의 Inquiry 우측에 있는 버튼입니다. 선택된 탭에 해당하는 버튼에 따라 show/hide 처리 부탁드립니다.
    tabMain.getFrame(tabMain.getSelectedTabID()).scope.scwin.tabInit();
};
scwin.onpageunload = function() {};
scwin.tabMain_onchange = function(tabID, idx, userTabID) {
    scvar.vTabId = tabMain.getSelectedTabID();
    tabMain.getFrame(scvar.vTabId).scope.scwin.tabInit();
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabMain_contents_content1_body_tabSubMain_tab_tabs2').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabMain_contents_content1_body_btn_inquiry').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
